$content = Get-Content "C:\Temp\vhplan-verify-fillportions\ScreenVhPlan.pa.yaml" -Raw
# Split on each control block start into pseudo-records to check whether each GroupContainer/Gallery block contains FillPortions before the next control starts
$lines = Get-Content "C:\Temp\vhplan-verify-fillportions\ScreenVhPlan.pa.yaml"
$count = $lines.Count
$missing = @()
for ($i=0; $i -lt $count; $i++) {
    if ($lines[$i] -match '^\s*Control: (GroupContainer|Gallery)\s*$') {
        # search forward until next 'Control:' or 'Children:' or end, up to ~40 lines, for FillPortions
        $found = $false
        for ($j=$i+1; $j -lt [Math]::Min($i+45,$count); $j++) {
            if ($lines[$j] -match 'FillPortions') { $found = $true; break }
            if ($lines[$j] -match '^\s*Control:') { break }
            if ($lines[$j] -match '^\s*Children:') { break }
        }
        if (-not $found) {
            # get control name from a few lines above
            $nameLine = ""
            for ($k=$i-1; $k -ge [Math]::Max($i-3,0); $k--) {
                if ($lines[$k] -match '^\s*- (\w+):\s*$') { $nameLine = $matches[1]; break }
            }
            $missing += "$($i+1): $nameLine"
        }
    }
}
"Missing count: " + $missing.Count
$missing | Select-Object -First 30

